    // --- HdrTransfer: the half-float conversions and the two HDR electro-optical transfer
    //     functions, which the wide-color decode paths below all depend on being right. ---
    {
        using Engine::Detail::float_to_half;
        using Engine::Detail::half_to_float;

        // Exact values every IEEE 754 binary16 implementation must agree on.
        assert(float_to_half(0.0f) == 0x0000);
        assert(float_to_half(-0.0f) == 0x8000);
        assert(float_to_half(1.0f) == 0x3C00);
        assert(float_to_half(-2.0f) == 0xC000);
        assert(float_to_half(65504.0f) == 0x7BFF);            // Largest finite half.
        assert(float_to_half(131008.0f) == 0x7C00);           // Overflows: +infinity.
        assert(float_to_half(6.103515625e-05f) == 0x0400);    // Smallest normal.
        assert(float_to_half(5.960464477539063e-08f) == 0x0001); // Smallest subnormal.
        assert(float_to_half(1e-10f) == 0x0000);              // Underflows: flushed to zero.

        assert(half_to_float(0x3C00) == 1.0f);
        assert(half_to_float(0xC000) == -2.0f);
        assert(half_to_float(0x0400) == 6.103515625e-05f);
        assert(half_to_float(0x0001) == 5.960464477539063e-08f);
        assert(half_to_float(0x7BFF) == 65504.0f);

        // Round-tripping every representable half through float and back must be exact, which is
        // what makes the EXR path's straight memcpy of half data safe to reason about.
        for (u32 bits = 0; bits <= 0xFFFF; ++bits) {
            const u16 half = static_cast<u16>(bits);
            const u16 exponent = static_cast<u16>((half >> 10) & 0x1F);
            const u16 mantissa = static_cast<u16>(half & 0x3FF);
            if (exponent == 0x1F && mantissa != 0) {
                continue; // NaN: not required to round-trip its exact payload.
            }
            assert(float_to_half(half_to_float(half)) == half);
        }
    }

    {
        using Engine::Detail::TransferFunction;
        using Engine::Detail::hlg_eotf_to_linear;
        using Engine::Detail::pq_eotf_to_linear;
        using Engine::Detail::transfer_function_from_h273;

        assert(transfer_function_from_h273(1) == TransferFunction::Srgb);
        assert(transfer_function_from_h273(13) == TransferFunction::Srgb);
        assert(transfer_function_from_h273(8) == TransferFunction::Linear);
        assert(transfer_function_from_h273(16) == TransferFunction::Pq);
        assert(transfer_function_from_h273(18) == TransferFunction::Hlg);
        assert(transfer_function_from_h273(2) == TransferFunction::Unsupported);

        // PQ: 0 is absolute black, and 1.0 is the format's 10000 cd/m^2 peak, which under this
        // engine's 1.0 == 100 cd/m^2 convention is 100.0.
        assert(pq_eotf_to_linear(0.0f) == 0.0f);
        assert(std::abs(pq_eotf_to_linear(1.0f) - 100.0f) < 0.01f);
        // The ST 2084 code value for 100 cd/m^2 (SDR reference white) is ~0.5081, which must come
        // back as 1.0 in the same convention.
        assert(std::abs(pq_eotf_to_linear(0.5081f) - 1.0f) < 0.01f);
        // Monotonic, which anything claiming to be an EOTF must be.
        for (int i = 1; i <= 100; ++i) {
            assert(pq_eotf_to_linear(static_cast<f32>(i) / 100.0f) >
                   pq_eotf_to_linear(static_cast<f32>(i - 1) / 100.0f));
        }

        // HLG: the standard fixes these two points exactly -- 0 maps to 0, and the 0.5 signal
        // level sits at the 1/12 join between the curve's square-law and logarithmic halves.
        assert(hlg_eotf_to_linear(0.0f) == 0.0f);
        assert(std::abs(hlg_eotf_to_linear(0.5f) - 1.0f / 12.0f) < 1e-5f);
        assert(std::abs(hlg_eotf_to_linear(1.0f) - 1.0f) < 1e-4f);
        for (int i = 1; i <= 100; ++i) {
            assert(hlg_eotf_to_linear(static_cast<f32>(i) / 100.0f) >
                   hlg_eotf_to_linear(static_cast<f32>(i - 1) / 100.0f));
        }
    }

    {
        using Engine::Detail::PixelFormat;
        assert(Engine::Detail::bytes_per_pixel(PixelFormat::Rgba8) == 4);
        assert(Engine::Detail::bytes_per_pixel(PixelFormat::Rgba16) == 8);
        assert(Engine::Detail::bytes_per_pixel(PixelFormat::Rgba16F) == 8);
        assert(Engine::Detail::bytes_per_pixel(PixelFormat::Rgba32F) == 16);
    }

