    {
            static constexpr u8 kRadianceHdr[] = {
                0x23, 0x3F, 0x52, 0x41, 0x44, 0x49, 0x41, 0x4E, 0x43, 0x45, 0x0A, 0x46, 0x4F, 0x52, 0x4D,
                0x41, 0x54, 0x3D, 0x33, 0x32, 0x2D, 0x62, 0x69, 0x74, 0x5F, 0x72, 0x6C, 0x65, 0x5F, 0x72,
                0x67, 0x62, 0x65, 0x0A, 0x0A, 0x2D, 0x59, 0x20, 0x32, 0x20, 0x2B, 0x58, 0x20, 0x32, 0x0A,
                0x80, 0x10, 0x08, 0x83, 0x10, 0x80, 0x08, 0x83, 0x08, 0x10, 0x80, 0x83, 0xCC, 0xCC, 0xCC,
                0x7D
            };
        const std::vector<std::byte> encoded(reinterpret_cast<const std::byte *>(kRadianceHdr),
                                             reinterpret_cast<const std::byte *>(kRadianceHdr) + sizeof(kRadianceHdr));

        Engine::Detail::DecodeOptions native;
        native.precision = Engine::Detail::DecodePrecision::Native;
        auto wide = Engine::Detail::decode_image(encoded, native, std::filesystem::path{"test.hdr"});
        assert(wide.has_value());
        assert(wide->format == Engine::Detail::PixelFormat::Rgba32F);
        assert(wide->transfer_function == 8); // Linear.
        assert(wide->pixels().size() == static_cast<usize>(wide->width) * wide->height * 16);
        f32 red = 0.0f;
        std::memcpy(&red, wide->pixels().data(), sizeof(red));
        assert(red > 1.5f); // Above SDR white: exactly what an 8-bit decode would have clamped.

        // The same file through the default path is clamped and sRGB-encoded, so that highlight
        // becomes saturated white rather than staying a float.
        auto narrow = Engine::Detail::decode_image_rgba8(encoded, std::filesystem::path{"test.hdr"});
        assert(narrow.has_value());
        assert(narrow->format == Engine::Detail::PixelFormat::Rgba8);
        assert(std::to_integer<u8>(narrow->pixels()[0]) == 255);
    }

    // --- 10-bit PQ AVIF: real HDR, the reason browsers ship AVIF for photos. The native path must
    //     keep 16-bit samples and report the file's own cICP transfer function. ---
