        assert(!full->is_preview);

        // JXL's DC frame is an eighth-scale approximation stored up front; flushing it yields an
        // image at the full canvas size but only DC-level detail, without the remaining passes
        // ever being decoded.
        Engine::Detail::DecodeOptions preview;
        preview.preview_min_dimension = 64;
        auto quick = Engine::Detail::decode_image(encoded, preview, std::filesystem::path{"prev.jxl"});
        assert(quick.has_value());
        assert(quick->is_preview);
        assert(quick->frames.size() == 1);
        assert(quick->pixels().size() == static_cast<usize>(quick->width) * quick->height * 4);
        assert(quick->full_width == 512 && quick->full_height == 512);
