        assert(all.has_value());
        assert(all->width == 2 && all->height == 2);
        // Three animation frames, not four: the white default image is not one of them.
        assert(all->frames.size() == 3);
        assert(std::to_integer<u8>(all->frames[0].pixels[0]) == 255); // Red.
        assert(std::to_integer<u8>(all->frames[0].pixels[1]) == 0);
        assert(std::to_integer<u8>(all->frames[1].pixels[1]) == 255); // Green.
        assert(std::to_integer<u8>(all->frames[2].pixels[2]) == 255); // Blue.

        // A still decode still shows the fallback, which is exactly its purpose.
        auto still = Engine::Detail::decode_image_rgba8(encoded, std::filesystem::path{"anim-default.png"});
